/* xx_zlib_extractor.c - search raw data for ZLIB.
 *
 * Scans for:
 *   78 01 at +0  ("x.")
 *   78 5E at +0  ("x^")
 *   78 9C at +0  ("x.")
 *   78 DA at +0  ("x.")
 * (hand-written: the detector establishes this signature outside its
 * 64-byte prefilter window)
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the zlib reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/zlib/xx_zlib.h"

static const uint8_t k_anchor0[] = { 0x78, 0x01 };
static const uint8_t k_anchor1[] = { 0x78, 0x5E };
static const uint8_t k_anchor2[] = { 0x78, 0x9C };
static const uint8_t k_anchor3[] = { 0x78, 0xDA };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
    { k_anchor1, sizeof(k_anchor1), 0U },
    { k_anchor2, sizeof(k_anchor2), 0U },
    { k_anchor3, sizeof(k_anchor3), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_ZLIB };

static Abstractformat *xx_zlib_search_open(xx_io_device *window) {
    xx_zlib *reader = xx_zlib_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_zlib_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_zlib_free((xx_zlib *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_zlib_search_open, xx_zlib_search_close
};

static xx_format_search_state *xx_zlib_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_zlib_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_zlib_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_zlib_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_zlib_extractor = {
    xx_zlib_create_format_search,
    xx_zlib_get_current_format_info,
    xx_zlib_format_search_find_next,
    xx_zlib_free_format_search
};
